-- gen621: 13 zone cambiate, 27 tessere
-- 33979df5b436f10204137719e14a7d06 (1042138) → c230922976fc1191d6f38b868edb753f (1047212)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'c230922976fc1191d6f38b868edb753f' as combacia
from kv_store where key like 'tmp:gen621:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen621:p%')
where key='app:jsx:src'
  and md5(value) = '33979df5b436f10204137719e14a7d06'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen621:p%') = 'c230922976fc1191d6f38b868edb753f';

update kv_store set value = '{"len":1047212,"ver":"gen-6.21"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'c230922976fc1191d6f38b868edb753f';

delete from kv_store where key like 'tmp:gen621:p%';
